import * as React from "react";
import {Icon,type IconProps} from "@/components/ui/icon";

export type NonBinaryIconProps=Omit<IconProps,"name">;
/** Lucide "non-binary" through the Cojeev Icon: motion presets, sizes and feedback included. */
export function NonBinaryIcon(props:NonBinaryIconProps){return <Icon name="non-binary" {...props}/>;}
